// Post-build patch: the @netlify/vite-plugin SSR handler is generated with
// `path: "/*"` and no exclusions, so it intercepts *every* request — including
// the POST our contact form makes. `preferStatic` only bypasses the function
// for GET requests to existing static files, never POSTs, so form submissions
// would hit the SSR handler (200, homepage) and never reach Netlify's form
// ingestion. We exclude the form endpoint so those POSTs bypass the catch-all.
//
// This file is regenerated by `vite build`, so this patch must run after it.
import { readFileSync, writeFileSync, existsSync } from "node:fs";

const FN = ".netlify/v1/functions/server.mjs";
const EXCLUDE = "/__forms.html";

if (!existsSync(FN)) {
  console.error(`[netlify-forms-fix] ${FN} not found — did the build run?`);
  process.exit(1);
}

let src = readFileSync(FN, "utf8");

if (src.includes("excludedPath")) {
  console.log("[netlify-forms-fix] excludedPath already present — skipping.");
} else if (src.includes('path: "/*",')) {
  src = src.replace('path: "/*",', `path: "/*",\n  excludedPath: "${EXCLUDE}",`);
  writeFileSync(FN, src);
  console.log(`[netlify-forms-fix] added excludedPath "${EXCLUDE}" to ${FN}`);
} else {
  console.error(
    `[netlify-forms-fix] could not find \`path: "/*",\` in ${FN}; ` +
      "the plugin output may have changed — review manually.",
  );
  process.exit(1);
}
